STORIES_GENRE_10 = [{'id': '091', 'title_vi': 'Ta Làm Mẹ Kế Ở Thập Niên 80', 'title_cn': '我在八零年代当后妈', 'author': 'Cà Chua / Đỗ Hoa', 'platform': 'Fanqie & Douyin (Hiện tượng phòng vé đoản kịch Tết 2024)', 'category': 'Niên đại văn / Xuyên thư sảng kịch / Mẹ kế làm giàu / Vả mặt cực phẩm', 'premise': "Nữ sinh viên đại học hiện đại Tư Niệm xuyên vào một cuốn tiểu thuyết thập niên 80, trở thành cô gái nông thôn bị gia đình ép gả thay cho một người đàn ông góa vợ có hai đứa con riêng ở làng bên để đổi lấy tiền sính lễ cho em trai. Ai cũng tưởng cô sẽ rơi vào địa ngục trần gian. Nhưng người chồng 'góa vợ' thực chất là một anh chàng thợ mộc lực lưỡng, đẹp trai, giỏi kinh doanh và cưng chiều vợ hết mực. Tư Niệm dùng kiến thức thời hiện đại mở xưởng may mặc, dẫn dắt cả gia đình làm giàu thành triệu phú đầu tiên của vùng quê.", 'characters': ['Tư Niệm: Thông minh, xinh đẹp, miệng lưỡi sắc bén, không bao giờ chịu thiệt dù chỉ nửa bước, chuyên trị các loại cực phẩm họ hàng. Mỏ neo: Chiếc thước dây đo may quần áo và cuốn sổ vẽ mẫu thời trang.', 'Chu Việt Thâm (Chồng thợ mộc): Cao to vạm vỡ, ít nói, làm việc chăm chỉ, nắm giữ nghề mộc mỹ nghệ gia truyền và yêu vợ say đắm.', "Hai đứa con riêng: Ban đầu phòng thủ sợ mẹ kế đánh đập, sau đó bị các món ăn ngon và tình yêu thương của cô thuần hóa thành hai 'fan cuồng' của mẹ."], 'hook_3s': "Bà thím độc ác hất đổ chậu nước giặt trước cửa nhà tôi cười nhạo: 'Thứ đàn bà lười biếng đi làm mẹ kế cho thằng thợ mộc góa vợ thì cả đời chỉ có ăn cám!'. Tôi rút ngay xấp tiền mười nghìn dày cộp quất thẳng vào mặt bà ta: 'Tiền này đủ mua đứt cả căn nhà của bà chưa?'.", 'act_structure': {'act_1': 'Hồi 1 (Màn lật kèo ngày cưới): Vừa về nhà chồng đã tay đôi vả mặt mẹ chồng cũ và đám họ hàng đến ăn chực; sắp xếp lại nhà cửa gọn gàng, nấu bữa cơm thịt kho thơm nức mũi.', 'act_2': 'Hồi 2 (Khởi nghiệp xưởng may niên đại): Thiết kế mẫu quần bò ống loe và áo sơ mi hoa nhí làm bùng nổ thị trường thời trang huyện lỵ; chồng mở xưởng đóng đồ gỗ mỹ nghệ xuất khẩu.', 'act_3': 'Hồi 3 (Trở thành đại gia tộc): Mua nhà mặt phố ở thủ đô, đưa hai con đỗ đại học danh tiếng; đám họ hàng cực phẩm năm xưa nhìn gia đình cô giàu có mà nuốt nước mắt tiếc nuối.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Hai đứa con nhỏ thực chất không phải con riêng của Chu Việt Thâm; đó là con của người đồng đội liệt sĩ đã hy sinh trên chiến trường biên giới được anh nhận nuôi và coi như con đẻ; Tư Niệm thực sự là mối tình đầu tiên của cuộc đời anh.', 'mastery_takeaways': ['Công thức thành công của Thập niên 80 (The 80s Nostalgia Formula): Kết hợp giữa không khí hoài niệm của thời kỳ đổi mới kinh tế với nhịp độ vả mặt nhanh, dứt khoát của phim ngắn hiện đại.', 'Hôn nhân tôn trọng và ngọt ngào (Power Couple Dynamics): Cả hai vợ chồng cùng có năng lực lao động và bảo vệ lẫn nhau trước mọi định kiến xã hội.', "Mẹo chuyển thể Audio TikTok: Tiếng máy may đạp chân 'xình xịch', tiếng đếm tiền rột rẹt, giọng đọc nữ tươi vui, đanh thép, tiết tấu dồn dập."], 'title_vn': 'Ta Làm Mẹ Kế Ở Thập Niên 80', 'genre': 'Niên đại văn / Xuyên thư sảng kịch / Mẹ kế làm giàu / Vả mặt cực phẩm', 'golden_hook': "Bà thím độc ác hất đổ chậu nước giặt trước cửa nhà tôi cười nhạo: 'Thứ đàn bà lười biếng đi làm mẹ kế cho thằng thợ mộc góa vợ thì cả đời chỉ có ăn cám!'. Tôi rút ngay xấp tiền mười nghìn dày cộp quất thẳng vào mặt bà ta: 'Tiền này đủ mua đứt cả căn nhà của bà chưa?'.", 'author_platform': 'Cà Chua / Đỗ Hoa - Fanqie & Douyin (Hiện tượng phòng vé đoản kịch Tết 2024)', 'core_lessons': ['Công thức thành công của Thập niên 80 (The 80s Nostalgia Formula): Kết hợp giữa không khí hoài niệm của thời kỳ đổi mới kinh tế với nhịp độ vả mặt nhanh, dứt khoát của phim ngắn hiện đại.', 'Hôn nhân tôn trọng và ngọt ngào (Power Couple Dynamics): Cả hai vợ chồng cùng có năng lực lao động và bảo vệ lẫn nhau trước mọi định kiến xã hội.', "Mẹo chuyển thể Audio TikTok: Tiếng máy may đạp chân 'xình xịch', tiếng đếm tiền rột rẹt, giọng đọc nữ tươi vui, đanh thép, tiết tấu dồn dập."]}, {'id': '092', 'title_vi': 'Ái Chà, Hoàng Hậu Nương Nương Đi Làm Thuê', 'title_cn': '哎呀，皇后娘娘来打工', 'author': 'Douyin', 'platform': 'Douyin (Hiện tượng cổ xuyên kim bạo hồng toàn mạng)', 'category': 'Cổ xuyên kim / Hài hước thương trường / Cung đấu giáng kích / Vả mặt tra nam', 'premise': "Hoàng hậu nương nương mẫu nghi thiên hạ thời cổ đại bất ngờ xuyên không vào thân xác của một cô vợ nhu nhược của tổng tài hào môn thời hiện đại, người đang bị chồng lạnh nhạt, mẹ chồng khinh bỉ và tiểu tam bắt nạt tại nơi làm việc. Đem toàn bộ 18 ban võ nghệ cung đấu và thuật dùng người chốn thâm cung sang áp dụng vào môi trường công sở hiện đại, Hoàng hậu nương nương biến phòng làm việc thành 'hậu cung thu nhỏ', từng bước thăng tiến làm Chủ tịch tập đoàn và trừng trị thẳng tay kẻ phụ bạc.", 'characters': ['Dung Nhĩ (Hoàng hậu xuyên không): Khí chất đoan trang quyền uy bẩm sinh, lời nói mềm mỏng nhưng giết người không thấy máu, nắm vững thuật trị quốc bình thiên hạ. Mỏ neo: Tách trà sứ thanh hoa và nụ cười mỉm lạnh lùng.', 'Tổng tài cựu chồng: Tự cao tự đại, ngơ ngác khi thấy người vợ nhu nhược bỗng biến thành vị nữ vương quyền lực mà mình phải ngước nhìn.', 'Tiểu tam công sở: Dùng mấy chiêu trà xanh hạ đẳng thời hiện đại bị Hoàng hậu bóc trần trong vòng 3 câu nói.'], 'hook_3s': "Ả tiểu tam cố tình đổ cốc cà phê nóng vào váy tôi ăn vạ: 'Chị dâu ơi, em không cố ý mà!'. Tôi thong thả rút khăn tay lụa lau nhẹ ngón tay, mỉm cười dịu dàng: 'Bổn cung còn chưa ban thưởng, ai cho phép một tiện tì như ngươi tự ý diễn trò trước mặt ta?'.", 'act_structure': {'act_1': "Hồi 1 (Cung đấu giáng cấp công sở): Áp dụng phép tắc cung cấm chấn chỉnh lại trật tự phòng ban; dùng thuật 'Ly gián' khiến nhóm tiểu tam và đồng nghiệp xấu tự cắn xé lẫn nhau.", 'act_2': 'Hồi 2 (Thao túng hội đồng quản trị): Dùng mưu lược bang giao xử lý các đối tác nước ngoài khó tính; ký kết hợp đồng sáp nhập nghìn tỷ cứu tập đoàn khỏi nguy cơ sụp đổ.', 'act_3': 'Hồi 3 (Phế truất tra nam): Nắm giữ 51% quyền biểu quyết, phế truất chức vụ tổng tài của gã chồng bất tài, đưa gã về làm nhân viên tạp vụ dọn nhà vệ sinh; tự mình ngồi lên ghế Chủ tịch hội đồng quản trị.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Vị Chủ tịch sáng lập tập đoàn ẩn danh từ nước ngoài trở về chính là vị Hoàng đế năm xưa cũng xuyên không theo nàng; nhưng lần này ngài chỉ dám đóng vai trợ lý trung thành xách túi cho Hoàng hậu nương nương.', 'mastery_takeaways': ['Hiệu ứng Giáng cấp chiêu thức (Dimensional Strike): Đem kỹ năng sinh tồn của đỉnh cao quyền lực (Hoàng cung) giáng xuống môi trường công sở bình thường tạo cảm giác áp đảo tuyệt đối và tiếng cười hả hê.', 'Ngôn từ cổ điển quý phái: Sử dụng đại từ xưng hô và phong thái lễ nghi cung đình tạo sự tương phản hài hước với văn hóa công sở hiện đại.', 'Mẹo chuyển thể Audio TikTok: Tiếng đàn tranh cổ phong tấu lên kiêu hãnh giữa không gian văn phòng kính hiện đại, tiếng guốc cao gót bước đi dõng dạc.'], 'title_vn': 'Ái Chà, Hoàng Hậu Nương Nương Đi Làm Thuê', 'genre': 'Cổ xuyên kim / Hài hước thương trường / Cung đấu giáng kích / Vả mặt tra nam', 'golden_hook': "Ả tiểu tam cố tình đổ cốc cà phê nóng vào váy tôi ăn vạ: 'Chị dâu ơi, em không cố ý mà!'. Tôi thong thả rút khăn tay lụa lau nhẹ ngón tay, mỉm cười dịu dàng: 'Bổn cung còn chưa ban thưởng, ai cho phép một tiện tì như ngươi tự ý diễn trò trước mặt ta?'.", 'author_platform': 'Douyin - Douyin (Hiện tượng cổ xuyên kim bạo hồng toàn mạng)', 'core_lessons': ['Hiệu ứng Giáng cấp chiêu thức (Dimensional Strike): Đem kỹ năng sinh tồn của đỉnh cao quyền lực (Hoàng cung) giáng xuống môi trường công sở bình thường tạo cảm giác áp đảo tuyệt đối và tiếng cười hả hê.', 'Ngôn từ cổ điển quý phái: Sử dụng đại từ xưng hô và phong thái lễ nghi cung đình tạo sự tương phản hài hước với văn hóa công sở hiện đại.', 'Mẹo chuyển thể Audio TikTok: Tiếng đàn tranh cổ phong tấu lên kiêu hãnh giữa không gian văn phòng kính hiện đại, tiếng guốc cao gót bước đi dõng dạc.']}, {'id': '093', 'title_vi': 'Mạt Thế Tích Trữ Trăm Tỷ Vật Tư', 'title_cn': '末世囤货百亿', 'author': 'Cà Chua / Tri Hồ', 'platform': 'Fanqie & Zhihu (Bạo khoản mạt thế tích trữ)', 'category': 'Mạt thế sinh tồn / Trọng sinh / Không gian thứ nguyên / Tích trữ vật tư khổng lồ', 'premise': 'Kiếp trước, Giang Thần bị người bạn gái thanh mai trúc mã và người bạn thân đẩy vào bầy xác sống để cướp mẩu bánh mì cuối cùng trong trận đại hồng thủy mạt thế. Trọng sinh về thời điểm trước khi thảm họa xảy ra 30 ngày, Giang Thần thức tỉnh không gian thứ nguyên vô hạn có khả năng bảo quản thực phẩm vĩnh viễn không ôi thiu. Anh lập tức bán tháo toàn bộ cổ phần công ty, vay nợ ngân hàng và bắt đầu chiến dịch tích trữ 100 nghìn tấn thịt hộp, mì tôm, thuốc men, xăng dầu và xây dựng boong-ke pháo đài thép kiên cố nhất thế giới.', 'characters': ['Giang Thần: Lạnh lùng, quyết đoán, mang tâm thế kẻ sinh tồn thực dụng, không có lòng thương hại rẻ rúng cho những kẻ phản bội. Mỏ neo: Chiếc nhẫn không gian màu đen tuyền và súng săn hai nòng.', 'Bạn gái cũ trà xanh: Khi mạt thế đến phải ăn vỏ cây dưới trời mưa bão, quỳ lạy trước cửa kính chống đạn của anh xin một ngụm nước.', 'Đội ngũ kỹ sư xây dựng: Giúp anh gia cố căn hộ tầng 28 thành boong-ke chống đạn ba lớp.'], 'hook_3s': "Tôi cầm xấp séc một trăm tỷ trên tay, lạnh lùng chỉ vào kho lương thực lớn nhất miền Bắc: 'Toàn bộ năm mươi nghìn tấn gạo, hai mươi nghìn tấn thịt bò đông lạnh và kho thuốc kháng sinh này... tôi mua đứt toàn bộ tiền mặt giao trong đêm nay!'.", 'act_structure': {'act_1': 'Hồi 1 (Chiến dịch quét sạch siêu thị): 30 ngày đếm ngược tích trữ hàng triệu tấn nhu yếu phẩm, máy phát điện diesel, tấm pin năng lượng mặt trời và hệ thống lọc nước RO.', 'act_2': 'Hồi 2 (Thảm họa ập xuống): Mưa axit và đại dịch xác sống tràn ngập thành phố; người ngoài đói khát giết chém lẫn nhau; Giang Thần trong boong-ke bật điều hòa 24 độ ăn lẩu bò thượng hạng ngắm tuyết rơi.', 'act_3': 'Hồi 3 (Thanh toán nợ máu): Đám bạn phản bội kiếp trước tìm đến định cạy cửa cướp đồ; anh kích hoạt hệ thống điện cao thế 10 nghìn vôn và van xả khí cay tiễn toàn bộ kẻ thù xuống địa ngục.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Không gian thứ nguyên của anh thực chất là khoang dự trữ của một con tàu cứu sinh văn minh ngoài hành tinh; khi thế giới mặt đất sụp đổ hoàn toàn, boong-ke của anh kích hoạt động cơ phản lực đưa những người sống sót ưu tú rời khỏi Trái Đất.', 'mastery_takeaways': ['Khoái cảm Tâm lý Tích trữ (Hoarding Dopamine Rush): Việc liệt kê các danh mục vật tư khổng lồ và cảm giác chuẩn bị chu đáo mang lại sự thỏa mãn tâm lý an toàn cực lớn cho người nghe.', 'Tương phản cực đoan giữa thiên đường và địa ngục: Cảnh ăn lẩu bò ấm áp bên trong đối lập với sự chết chóc đói rét bên ngoài tạo điểm sảng tuyệt đối.', 'Mẹo chuyển thể Audio TikTok: Tiếng còi báo động mạt thế hú vang khắp thành phố, tiếng xèo xèo nhúng thịt vào nồi lẩu nghi ngút khói.'], 'title_vn': 'Mạt Thế Tích Trữ Trăm Tỷ Vật Tư', 'genre': 'Mạt thế sinh tồn / Trọng sinh / Không gian thứ nguyên / Tích trữ vật tư khổng lồ', 'golden_hook': "Tôi cầm xấp séc một trăm tỷ trên tay, lạnh lùng chỉ vào kho lương thực lớn nhất miền Bắc: 'Toàn bộ năm mươi nghìn tấn gạo, hai mươi nghìn tấn thịt bò đông lạnh và kho thuốc kháng sinh này... tôi mua đứt toàn bộ tiền mặt giao trong đêm nay!'.", 'author_platform': 'Cà Chua / Tri Hồ - Fanqie & Zhihu (Bạo khoản mạt thế tích trữ)', 'core_lessons': ['Khoái cảm Tâm lý Tích trữ (Hoarding Dopamine Rush): Việc liệt kê các danh mục vật tư khổng lồ và cảm giác chuẩn bị chu đáo mang lại sự thỏa mãn tâm lý an toàn cực lớn cho người nghe.', 'Tương phản cực đoan giữa thiên đường và địa ngục: Cảnh ăn lẩu bò ấm áp bên trong đối lập với sự chết chóc đói rét bên ngoài tạo điểm sảng tuyệt đối.', 'Mẹo chuyển thể Audio TikTok: Tiếng còi báo động mạt thế hú vang khắp thành phố, tiếng xèo xèo nhúng thịt vào nồi lẩu nghi ngút khói.']}, {'id': '094', 'title_vi': 'Kỷ Băng Hà: Phòng Trọ Hằng Nhiệt Của Ta', 'title_cn': '冰河纪：恒温出租屋', 'author': 'Tri Hồ', 'platform': 'Zhihu (Mạt thế sinh tồn thực tế)', 'category': 'Kỷ băng hà tận thế / Âm 60 độ C / Kỹ thuật sinh tồn / Boong-ke phòng trọ', 'premise': 'Hiện tượng biến đổi khí hậu cực đoan đẩy Trái Đất vào Kỷ Băng Hà vĩnh cửu trong vòng 24 giờ, nhiệt độ ngoài trời giảm sốc xuống âm 60 độ C, mạng lưới điện lưới quốc gia sụp đổ. Kỹ sư nhiệt điện Lục Bách nhờ kinh nghiệm nghề nghiệp đã cải tạo căn phòng trọ tầng 1 của mình thành một hệ thống hằng nhiệt khép kín: Tận dụng đường ống dẫn nhiệt ngầm của trạm biến áp bỏ hoang, cách nhiệt tường bằng 4 lớp xốp khí aerogel và nuôi nấm ăn trong phòng tắm. Anh phải đối đầu với những người hàng xóm tàn bạo tìm cách phá cửa cướp nguồn nhiệt.', 'characters': ['Lục Bách: Điềm tĩnh, nắm vững định luật nhiệt động lực học và kỹ thuật gia cố cơ học, coi sự sống sót là một bài toán kỹ thuật chính xác. Mỏ neo: Súng bắn đinh bê tông áp lực cao và nhiệt kế hồng ngoại kỹ thuật số.', "Trưởng ban quản lý tòa nhà: Kẻ chuyên đi hô hào 'đoàn kết chia sẻ lò sưởi' để vơ vét thức ăn của cư dân.", 'Nhóm côn đồ cùng tầng: Cầm xà beng và búa tạ tìm cách phá tường phòng trọ.'], 'hook_3s': "Nhiệt kế ngoài ban công tụt dốc không phanh xuống âm sáu mươi độ C, tiếng nứt toác của bê tông đóng băng rền rĩ khắp tòa nhà. Cửa phòng tôi rung chuyển dữ dội dưới nhát búa chim của gã hàng xóm: 'Mở cửa ra cho tao sưởi ấm, không tao đập chết cả nhà mày!'.", 'act_structure': {'act_1': 'Hồi 1 (Gia cố phòng tuyến nhiệt): Lắp đặt cửa thép hai lớp đệm bông gốm cách nhiệt, khóa van thông gió để giữ nhiệt độ phòng ổn định ở 20 độ C.', 'act_2': 'Hồi 2 (Chiến tranh tài nguyên trong bóng tối băng giá): Hàng xóm bắt đầu cắn xé lẫn nhau vì củi đốt và đồ ăn thừa; Lục Bách dùng bẫy điện cực ngầm bảo vệ cửa sổ.', 'act_3': 'Hồi 3 (Phản công sinh tồn): Dùng súng bắn đinh áp lực cao đẩy lùi đợt tấn công của nhóm cướp bóc; dùng hơi nước sôi áp lực cao phun ra từ van xả đóng băng toàn bộ kẻ địch thành những cột băng vĩnh cửu.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Nguồn nhiệt ngầm của anh không phải may mắn tự nhiên; cha anh là kỹ sư trưởng thiết kế tòa nhà này 30 năm trước đã âm thầm xây dựng một đường ống dẫn khí methane bí mật phòng ngừa thảm họa cho con trai.', 'mastery_takeaways': ['Kinh dị sinh tồn băng giá (Cryo-Survival Horror): Nỗi sợ hãi cái lạnh thấu xương và sự đóng băng của các cơ quan cơ thể tạo trải nghiệm cảm giác rùng mình chân thực.', "Chống lại thói 'Đạo đức bắt cóc' nơi mạt thế: Trừng trị thẳng tay những kẻ nhân danh tập thể để cướp bóc tài sản cá nhân.", "Mẹo chuyển thể Audio TikTok: Tiếng gió bão tuyết gầm rú thấu xương 'ùuuuuu', tiếng nứt gãy răng rắc của kính cửa sổ đóng băng."], 'title_vn': 'Kỷ Băng Hà: Phòng Trọ Hằng Nhiệt Của Ta', 'genre': 'Kỷ băng hà tận thế / Âm 60 độ C / Kỹ thuật sinh tồn / Boong-ke phòng trọ', 'golden_hook': "Nhiệt kế ngoài ban công tụt dốc không phanh xuống âm sáu mươi độ C, tiếng nứt toác của bê tông đóng băng rền rĩ khắp tòa nhà. Cửa phòng tôi rung chuyển dữ dội dưới nhát búa chim của gã hàng xóm: 'Mở cửa ra cho tao sưởi ấm, không tao đập chết cả nhà mày!'.", 'author_platform': 'Tri Hồ - Zhihu (Mạt thế sinh tồn thực tế)', 'core_lessons': ['Kinh dị sinh tồn băng giá (Cryo-Survival Horror): Nỗi sợ hãi cái lạnh thấu xương và sự đóng băng của các cơ quan cơ thể tạo trải nghiệm cảm giác rùng mình chân thực.', "Chống lại thói 'Đạo đức bắt cóc' nơi mạt thế: Trừng trị thẳng tay những kẻ nhân danh tập thể để cướp bóc tài sản cá nhân.", "Mẹo chuyển thể Audio TikTok: Tiếng gió bão tuyết gầm rú thấu xương 'ùuuuuu', tiếng nứt gãy răng rắc của kính cửa sổ đóng băng."]}, {'id': '095', 'title_vi': 'Vô Hạn Lưu: Thần Chết Cũng Phải Làm Thêm', 'title_cn': '无限流：死神也打工', 'author': 'Tri Hồ', 'platform': 'Zhihu (Châm biếm vô hạn lưu)', 'category': 'Vô hạn lưu / Tử thần làm việc theo ca / Sa điêu hài hước / Người chơi cày cuốc', 'premise': 'Tử thần tập sự số 9527 được phân công làm Boss cai quản tầng 1 của Tháp Sinh Tử Vô Hạn. Theo quy định, mỗi ngày anh phải thu hoạch 10 linh hồn người chơi để đủ chỉ tiêu KPI không bị trừ lương. Không may, anh đụng phải Diệp Hạo – một game thủ chuyên nghiệp cày chay mắc chứng nghiện game nặng. Diệp Hạo không những không sợ chết mà còn lợi dụng các cơ chế bug của Tử thần để farm điểm kinh nghiệm, cướp lưỡi hái của Tử thần đi gặt lúa và ép Tử thần phải tăng ca suốt đêm cày đồ cho mình.', 'characters': ['Tử thần số 9527: Thân mặc áo choàng đen rách rưới, cầm lưỡi hái nhưng luôn mệt mỏi vì chỉ tiêu KPI và sợ bị trừ điểm chuyên cần. Mỏ neo: Cuốn sổ sinh tử điện tử báo lỗi mạng 404.', 'Diệp Hạo (Người chơi cày chay): Mắt thâm quầng vì thức đêm chơi game, coi Tử thần như một NPC rơi đồ cấp cao.', 'Hội đồng Thần chết tối cao: Liên tục gửi thư cảnh cáo vì tầng 1 không giết được ai suốt một tháng.'], 'hook_3s': "Tôi vung lưỡi hái tử thần đen ngòm bổ xuống đầu tên người chơi: 'Chết đi phàm nhân!'. Hắn thong thả giơ chiếc khiên gỗ chặn lại một cách hoàn hảo, mắt sáng rực: 'Tuyệt vời! Cơ chế Parry chặn đòn chuẩn không lệch một khung hình, Boss ơi đánh lại lần nữa để tớ luyện combo nào!'.", 'act_structure': {'act_1': 'Hồi 1 (Nỗi khổ của Tử thần làm công ăn lương): Boss dùng đủ mọi chiêu thức sấm sét độc dược nhưng người chơi liên tục lộn nhào né đòn (I-frame) và đánh trả.', 'act_2': 'Hồi 2 (Thương lượng đình chiến): Tử thần kiệt sức xin người chơi tha cho mình để về ngủ; người chơi yêu cầu Tử thần phải ký hợp đồng cày thuê phó bản tầng trên để đổi lấy linh hồn giả.', 'act_3': 'Hồi 3 (Đại náo Tháp Vô Hạn): Người chơi cùng Tử thần liên thủ phá hủy toàn bộ hệ thống máy chủ của trò chơi bóc lột, giải phóng hàng triệu linh hồn người chơi và Boss trở về tự do.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Toàn bộ Tháp Sinh Tử thực chất là một máy chủ đào tiền ảo bất hợp pháp của một tập đoàn công nghệ; việc người chơi và Tử thần liên thủ đã kích hoạt mã virus tự hủy giải phóng năng lượng cho toàn thế giới.', 'mastery_takeaways': ['Giải cấu trúc thể loại Vô Hạn Lưu (Deconstruction of LitRPG): Biến sự tàn khốc của trò chơi sinh tử thành câu chuyện hài hước về áp lực lao động công sở và tinh thần game thủ.', 'Thuật ngữ game thủ chuẩn xác: Parry, I-frame (khung bất tử), hitbox, farm quái tạo sự thích thú cho cộng đồng yêu thích game.', "Mẹo chuyển thể Audio TikTok: Tiếng kim loại va chạm 'Kengggg' của đòn đỡ hoàn hảo, tiếng thở dài ngao ngán của Tử thần khi nghe chuông báo thức đi làm."], 'title_vn': 'Vô Hạn Lưu: Thần Chết Cũng Phải Làm Thêm', 'genre': 'Vô hạn lưu / Tử thần làm việc theo ca / Sa điêu hài hước / Người chơi cày cuốc', 'golden_hook': "Tôi vung lưỡi hái tử thần đen ngòm bổ xuống đầu tên người chơi: 'Chết đi phàm nhân!'. Hắn thong thả giơ chiếc khiên gỗ chặn lại một cách hoàn hảo, mắt sáng rực: 'Tuyệt vời! Cơ chế Parry chặn đòn chuẩn không lệch một khung hình, Boss ơi đánh lại lần nữa để tớ luyện combo nào!'.", 'author_platform': 'Tri Hồ - Zhihu (Châm biếm vô hạn lưu)', 'core_lessons': ['Giải cấu trúc thể loại Vô Hạn Lưu (Deconstruction of LitRPG): Biến sự tàn khốc của trò chơi sinh tử thành câu chuyện hài hước về áp lực lao động công sở và tinh thần game thủ.', 'Thuật ngữ game thủ chuẩn xác: Parry, I-frame (khung bất tử), hitbox, farm quái tạo sự thích thú cho cộng đồng yêu thích game.', "Mẹo chuyển thể Audio TikTok: Tiếng kim loại va chạm 'Kengggg' của đòn đỡ hoàn hảo, tiếng thở dài ngao ngán của Tử thần khi nghe chuông báo thức đi làm."]}, {'id': '096', 'title_vi': 'Tận Thế Mưa Axit: Kế Thừa Siêu Thị Trăm Tỷ', 'title_cn': '酸雨降临', 'author': 'Tri Hồ', 'platform': 'Zhihu (Chuyên mục Mạt thế thảm họa)', 'category': 'Thảm họa thiên nhiên / Mưa axit ăn mòn / Siêu thị ngầm / Trạm cứu hộ', 'premise': 'Trận mưa axit có độ pH bằng 1 trút xuống toàn cầu, ăn mòn bê tông cốt thép, làm tan chảy kính xe hơi và biến nguồn nước mặt thành kịch độc. Nữ chính may mắn kế thừa một siêu thị bán buôn ngầm 3 tầng dưới lòng đất của người cha quá cố, được xây dựng hoàn toàn bằng hợp kim chống ăn mòn và có nguồn nước khoáng ngầm độc lập. Cô thiết lập hệ thống phòng thủ nghiêm ngặt, mở trạm trao đổi nhu yếu phẩm công bằng cho những người sống sót có kỹ năng lao động.', 'characters': ["Tô Mạn: Bản lĩnh, thực tế, có kiến thức sâu rộng về hóa học và xử lý nước ô nhiễm, nguyên tắc rõ ràng 'không làm thì không có ăn'. Mỏ neo: Giấy quỳ tím đo độ pH và chiếc mặt nạ phòng độc quân sự.", 'Gia đình chú ruột tham lam: Đòi vào chiếm quyền kiểm soát siêu thị nhưng bị cô dùng vòi rồng nước vôi trung hòa đuổi đi.', 'Nhóm thợ cơ khí và bác sĩ: Những người sống sót tài năng được cô thu nhận vào cộng đồng.'], 'hook_3s': "Một giọt nước mưa rơi xuống mu bàn tay người đàn ông bốc khói xèo xèo, ăn mòn da thịt lộ ra cả xương trắng trong ba giây: 'Mưa axit! Toàn bộ nước mưa biến thành axit sulfuric rồi, chạy mau!'.", 'act_structure': {'act_1': 'Hồi 1 (Màn đêm ăn mòn): Mưa axit làm sập mái các tòa nhà cao tầng; người dân chạy loạn tìm nơi trú ẩn trong hoảng loạn.', 'act_2': 'Hồi 2 (Thiết lập quy tắc sinh tồn siêu thị ngầm): Tô Mạn dùng hóa chất kiềm trung hòa nước mưa ở lối vào; ban hành quy tắc đổi công lao động lấy đồ hộp và nước sạch.', 'act_3': 'Hồi 3 (Đẩy lùi làn sóng cướp bóc): Nhóm cướp dùng xe ủi đất tấn công cửa hầm; cô kích hoạt hệ thống phun dung dịch kiềm đậm đặc làm tê liệt vũ khí của chúng, bảo vệ an toàn cho hàng trăm người dân.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Người cha quá cố của cô từng là nhà khoa học khí tượng hàng đầu; ông đã dự báo trước thảm họa mưa axit từ 10 năm trước và xây dựng siêu thị ngầm này như một món quà sinh nhật cuối cùng để bảo vệ mạng sống cho con gái.', 'mastery_takeaways': ['Hiệu ứng thị giác Hóa học rùng rợn (Chemical Erosion Horror): Khói trắng bốc lên, kim loại rỉ sét trong chớp mắt, nước sôi sùng sục tạo nỗi sợ giác quan cực mạnh.', 'Mô hình Xã hội thu nhỏ (Micro-Society Building): Cách tổ chức phân chia lao động và nguồn lực hợp lý tạo sức hấp dẫn về mặt chiến lược quản trị.', 'Mẹo chuyển thể Audio TikTok: Tiếng mưa rơi rào rào xèo xèo ăn mòn mái tôn, tiếng rít báo động nguy cấp của còi phòng không.'], 'title_vn': 'Tận Thế Mưa Axit: Kế Thừa Siêu Thị Trăm Tỷ', 'genre': 'Thảm họa thiên nhiên / Mưa axit ăn mòn / Siêu thị ngầm / Trạm cứu hộ', 'golden_hook': "Một giọt nước mưa rơi xuống mu bàn tay người đàn ông bốc khói xèo xèo, ăn mòn da thịt lộ ra cả xương trắng trong ba giây: 'Mưa axit! Toàn bộ nước mưa biến thành axit sulfuric rồi, chạy mau!'.", 'author_platform': 'Tri Hồ - Zhihu (Chuyên mục Mạt thế thảm họa)', 'core_lessons': ['Hiệu ứng thị giác Hóa học rùng rợn (Chemical Erosion Horror): Khói trắng bốc lên, kim loại rỉ sét trong chớp mắt, nước sôi sùng sục tạo nỗi sợ giác quan cực mạnh.', 'Mô hình Xã hội thu nhỏ (Micro-Society Building): Cách tổ chức phân chia lao động và nguồn lực hợp lý tạo sức hấp dẫn về mặt chiến lược quản trị.', 'Mẹo chuyển thể Audio TikTok: Tiếng mưa rơi rào rào xèo xèo ăn mòn mái tôn, tiếng rít báo động nguy cấp của còi phòng không.']}, {'id': '097', 'title_vi': 'Khách Sạn Boong-ke Ngày Tận Thế', 'title_cn': '末日安全屋酒店', 'author': 'Tri Hồ', 'platform': 'Zhihu (Mạt thế nâng cấp khách sạn)', 'category': 'Mạt thế xác sống / Hệ thống nâng cấp / Khách sạn 5 sao / Vả mặt sảng khoái', 'premise': "Giữa đại dịch xác sống toàn cầu, Bạch Lạc thừa kế một khách sạn mini đổ nát ở ngoại ô và bất ngờ liên kết với 'Hệ Thống Khách Sạn Boong-ke Ngày Tận Thế'. Chỉ cần tiếp nhận khách thuê và thu thập tinh thể xác sống, khách sạn sẽ được nâng cấp: Tường chống đạn, kính cường lực nano, robot phục vụ 5 sao, quầy buffet không giới hạn và lưới điện phòng thủ laser tự động. Những kẻ quyền quý từng ruồng bỏ cô kiếp trước nay phải xếp hàng dài xin một tấm chiếu rách ở hành lang khách sạn.", 'characters': ['Bạch Lạc (Bà chủ khách sạn): Xinh đẹp, thanh lịch, luôn mặc sườn xám đỏ ngồi uống cà phê ở quầy lễ tân, nắm quyền sinh sát tuyệt đối trong khuôn viên khách sạn. Mỏ neo: Chiếc chuông bấm lễ tân bằng đồng sáng loáng.', 'Đội quân xác sống: Bất lực gầm rú ngoài hàng rào laser nhưng không thể bước qua nửa bước.', 'Gia đình kẻ thù cũ: Đói khát, rách rưới, van xin cô giảm giá tiền phòng bằng một viên bánh mì khô.'], 'hook_3s': "Bầy xác sống hàng vạn con gầm rú lao vào cổng khách sạn, vừa chạm vào hàng rào vô hình liền bị tia laser nano cắt thành từng mảnh vụn tro tàn. Tôi thong thả bấm chuông lễ tân: 'Phòng đơn một đêm mười viên tinh thể, thanh toán trước mới giao chìa khóa!'.", 'act_structure': {'act_1': 'Hồi 1 (Khai trương khách sạn an toàn nhất thế giới): Nâng cấp phòng trọ rách nát thành ốc đảo bình yên có điện nước và máy lạnh 24/7.', 'act_2': 'Hồi 2 (Thiết lập luật thép): Bất kỳ kẻ nào vi phạm quy tắc cấm đánh nhau trong khách sạn đều bị robot bảo vệ ném thẳng ra ngoài cho xác sống xâu xé.', 'act_3': 'Hồi 3 (Mở rộng thành pháo đài nhân loại): Khách sạn mở rộng quy mô thành thành phố ngầm chứa được mười vạn người, trở thành trung tâm phục hưng nền văn minh loài người mới.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Bản thân Bạch Lạc chính là Trùm nhiễm bệnh số 0 có khả năng miễn nhiễm hoàn toàn với virus; dòng máu của cô chính là kháng thể duy nhất giúp các nhà khoa học trong khách sạn điều chế vaccine cứu rỗi thế giới.', 'mastery_takeaways': ['Mô-típ Xây dựng kinh doanh nơi mạt thế (Base-Building Dopamine): Cảm giác nâng cấp từ căn phòng tồi tàn lên lâu đài sang trọng mang lại sự thỏa mãn vô tận.', 'Vả mặt bằng dịch vụ cao cấp: Để kẻ thù nhìn thấy mình sống xa hoa sung sướng giữa lúc chúng khốn cùng là đòn trả thù ngọt ngào nhất.', "Mẹo chuyển thể Audio TikTok: Tiếng chuông bấm lễ tân 'Keng!' ngân vang thanh thoát, đối lập với tiếng gầm rú điên loạn của bầy quái vật bên ngoài."], 'title_vn': 'Khách Sạn Boong-ke Ngày Tận Thế', 'genre': 'Mạt thế xác sống / Hệ thống nâng cấp / Khách sạn 5 sao / Vả mặt sảng khoái', 'golden_hook': "Bầy xác sống hàng vạn con gầm rú lao vào cổng khách sạn, vừa chạm vào hàng rào vô hình liền bị tia laser nano cắt thành từng mảnh vụn tro tàn. Tôi thong thả bấm chuông lễ tân: 'Phòng đơn một đêm mười viên tinh thể, thanh toán trước mới giao chìa khóa!'.", 'author_platform': 'Tri Hồ - Zhihu (Mạt thế nâng cấp khách sạn)', 'core_lessons': ['Mô-típ Xây dựng kinh doanh nơi mạt thế (Base-Building Dopamine): Cảm giác nâng cấp từ căn phòng tồi tàn lên lâu đài sang trọng mang lại sự thỏa mãn vô tận.', 'Vả mặt bằng dịch vụ cao cấp: Để kẻ thù nhìn thấy mình sống xa hoa sung sướng giữa lúc chúng khốn cùng là đòn trả thù ngọt ngào nhất.', "Mẹo chuyển thể Audio TikTok: Tiếng chuông bấm lễ tân 'Keng!' ngân vang thanh thoát, đối lập với tiếng gầm rú điên loạn của bầy quái vật bên ngoài."]}, {'id': '098', 'title_vi': 'Mạt Thế Thực Vật Tiến Hóa', 'title_cn': '植物进化的末日', 'author': 'Tri Hồ', 'platform': 'Zhihu (Mạt thế sinh thái)', 'category': 'Khoa học viễn tưởng / Thực vật biến dị / Nữ nhà thực vật học / Sinh tồn xanh', 'premise': 'Một trận bão mặt trời kích hoạt sự tiến hóa đột biến của toàn bộ loài thực vật trên Trái Đất: Dây leo thường xuân có thể siết nát xe tăng, hoa ăn thịt người khổng lồ mọc kín các ngã tư đường phố, cây liễu rủ có thể bắn ra hàng vạn gai độc như mưa tên. Nữ tiến sĩ thực vật học Khương Tảo vận dụng hiểu biết sâu sắc về hormone thực vật, pheromone và cơ chế quang hợp để điều khiển các loài cây biến dị, biến căn nhà kính trên sân thượng thành một pháo đài sinh học bất khả xâm phạm.', 'characters': ["Khương Tảo: Tỉnh táo, đam mê sinh học, nhìn mọi loài cây ăn thịt như những sinh vật cần được 'giao tiếp và thuần dưỡng'. Mỏ neo: Bình xịt hormone thực vật tự chế và kính hiển vi quang học bỏ túi.", 'Cây Đậu Hà Lan biến dị (Thú cưng): Có khả năng bắn hạt đậu với tốc độ âm thanh phá hủy động cơ xe hơi.', 'Dây hoa hồng gai: Trở thành hàng rào bảo vệ thông minh biết nhận diện mùi hương của chủ nhân.'], 'hook_3s': 'Dây thường xuân khổng lồ to bằng thân cây xà cừ cuốn chặt lấy chiếc xe bọc thép nâng bổng lên không trung rồi bóp nát bét như vỏ lon bia, tôi xịt nhẹ luồng hormone hoa cúc vào không khí, cành cây bỗng dịu dàng hạ xuống khẽ cọ vào vai tôi như một chú mèo con.', 'act_structure': {'act_1': 'Hồi 1 (Thành phố bê tông bị rừng rậm nuốt chửng): Cây cối phá vỡ đường nhựa mọc lên hàng trăm mét trong một đêm; con người trở thành con mồi trong chuỗi thức ăn mới.', 'act_2': 'Hồi 2 (Khoa học thuần hóa thực vật): Khương Tảo chiết xuất pheromone phấn hoa để ra lệnh cho các loài dây leo săn bắt thú dữ và lọc nước sạch cho căn cứ.', 'act_3': 'Hồi 3 (Giải cứu hạt giống nhân loại): Dẫn đầu đoàn thám hiểm đột nhập vào Ngân hàng Hạt giống Quốc gia, bảo tồn các nguồn gen cây trồng cổ điển để tái thiết lại nền nông nghiệp tương lai.'}, 'plot_twist': "Điểm bẻ lái cốt lõi: Sự tiến hóa của thực vật không phải thảm họa ngẫu nhiên; đó là cơ chế tự phòng vệ của Trái Đất để thanh lọc bầu không khí ô nhiễm do con người tàn phá; Khương Tảo được cây mẹ cổ thụ chọn làm 'Người phát ngôn sinh thái' của hành tinh.", 'mastery_takeaways': ['Chất liệu Mạt thế xanh (Eco-Apocalypse / Green Gothic): Thay thế quái vật xác sống truyền thống bằng rừng rậm biến dị mang lại màu sắc thị giác và thính giác hoàn toàn mới lạ.', 'Sức mạnh của Tri thức chuyên môn: Tôn vinh vẻ đẹp của khoa học thực nghiệm và sự hòa hợp tôn trọng thiên nhiên.', "Mẹo chuyển thể Audio TikTok: Tiếng rễ cây đâm toạc nền bê tông 'răng rắc', tiếng lá cây xào xạc thì thầm trong gió tạo không gian âm thanh huyền bí."], 'title_vn': 'Mạt Thế Thực Vật Tiến Hóa', 'genre': 'Khoa học viễn tưởng / Thực vật biến dị / Nữ nhà thực vật học / Sinh tồn xanh', 'golden_hook': 'Dây thường xuân khổng lồ to bằng thân cây xà cừ cuốn chặt lấy chiếc xe bọc thép nâng bổng lên không trung rồi bóp nát bét như vỏ lon bia, tôi xịt nhẹ luồng hormone hoa cúc vào không khí, cành cây bỗng dịu dàng hạ xuống khẽ cọ vào vai tôi như một chú mèo con.', 'author_platform': 'Tri Hồ - Zhihu (Mạt thế sinh thái)', 'core_lessons': ['Chất liệu Mạt thế xanh (Eco-Apocalypse / Green Gothic): Thay thế quái vật xác sống truyền thống bằng rừng rậm biến dị mang lại màu sắc thị giác và thính giác hoàn toàn mới lạ.', 'Sức mạnh của Tri thức chuyên môn: Tôn vinh vẻ đẹp của khoa học thực nghiệm và sự hòa hợp tôn trọng thiên nhiên.', "Mẹo chuyển thể Audio TikTok: Tiếng rễ cây đâm toạc nền bê tông 'răng rắc', tiếng lá cây xào xạc thì thầm trong gió tạo không gian âm thanh huyền bí."]}, {'id': '099', 'title_vi': 'Hoang Đảo Cầu Sinh 30 Ngày', 'title_cn': '荒岛求生三十天', 'author': 'Tri Hồ', 'platform': 'Zhihu (Sinh tồn thực tế)', 'category': 'Hiện đại sinh tồn / Gameshow hoang đảo / Bản chất con người / Trí tuệ nguyên thủy', 'premise': '10 người chơi thuộc các tầng lớp xã hội khác nhau (Tổng tài, Minh tinh, Bác sĩ, Thợ xây, Vận động viên) tham gia gameshow sinh tồn 30 ngày trên một hoang đảo biệt lập ở Thái Bình Dương để tranh giải thưởng 100 tỷ đồng. Khi một cơn bão quét qua phá hủy toàn bộ tàu tiếp tế của ban tổ chức, trò chơi biến thành cuộc chiến sinh tử ngoài đời thực. Tiền bạc, danh vọng mất sạch giá trị; chỉ có kỹ năng tạo lửa bằng đá cùi, lọc nước ngọt và dựng chòi của người thợ xây nghèo mới là thứ quyết định sự sống chết.', 'characters': ['Lão Triệu (Bác thợ xây): Dạn dày sương gió, ít nói, bàn tay chai sạn thạo việc chế tạo công cụ thô sơ từ tre nứa và đá san hô. Mỏ neo: Hòn đá lửa bọc vải khô và con dao đi rừng cùn.', 'Tổng tài kiêu ngạo: Cầm tấm séc 100 tỷ đòi mua một ngụm nước ngọt của Lão Triệu nhưng bị từ chối thẳng thừng.', 'Nữ minh tinh: Học cách nhặt ốc biển, nướng cá và trút bỏ lớp son phấn giả tạo để sinh tồn.'], 'hook_3s': "Tổng tài ném chiếc thẻ đen không giới hạn hạn mức vào đống tro tàn trước mặt tôi: 'Tôi cho ông mười tỷ, bán cho tôi nửa chai nước ngọt và con cá nướng đó!'. Tôi thong thả cắn ngập miệng thịt cá, cười nhạt: 'Ở đây, tờ tiền của anh không đáng giá bằng một hòn than củi sưởi ấm!'.", 'act_structure': {'act_1': 'Hồi 1 (Sự sụp đổ của trật tự văn minh): Bão cuốn trôi lương thực dự trữ; những kẻ quen được cung phụng trở nên bất lực đói khát; Lão Triệu dùng bẫy tre bắt được lợn rừng.', 'act_2': 'Hồi 2 (Đấu tranh nhân tính giữa lằn ranh đói khát): Có kẻ tìm cách trộm thức ăn và phá hoại nguồn nước ngọt; Lão Triệu thiết lập quy tắc công bằng bảo vệ nhóm người yếu thế.', 'act_3': 'Hồi 3 (Đốt lửa đón tàu cứu hộ): Vào ngày thứ 30, Lão Triệu chế tạo tín hiệu khói màu cam từ nhựa cây cứu cả đoàn người thoát chết trở về đất liền.'}, 'plot_twist': "Điểm bẻ lái cốt lõi: Vụ mất liên lạc với tàu tiếp tế thực chất là một phần thử thách tâm lý tột cùng của ban tổ chức; toàn bộ quá trình chia sẻ thức ăn và hy sinh của Lão Triệu được phát sóng trực tiếp cho hàng tỷ người xem, giúp ông được bình chọn là 'Anh hùng nhân cách' nhận trọn giải thưởng 100 tỷ.", 'mastery_takeaways': ['Giải thiêng Giá trị đồng tiền (Devaluing Currency in Crisis): Đặt nhân vật vào hoàn cảnh cực đoan để bộc lộ rõ nhất giá trị của lao động chân chính và kỹ năng sinh tồn thực tế.', 'Khắc họa tâm lý xã hội học sâu sắc: Sự chuyển biến tâm lý từ ích kỷ sang đoàn kết tương trợ lẫn nhau mang lại giá trị nhân văn cao đẹp.', "Mẹo chuyển thể Audio TikTok: Tiếng cọ xát của hai thanh gỗ đánh lửa 'xoẹt xoẹt xoẹt', tiếng ngọn lửa bùng lên tanh tách mang lại sự nhẹ nhõm vô bờ."], 'title_vn': 'Hoang Đảo Cầu Sinh 30 Ngày', 'genre': 'Hiện đại sinh tồn / Gameshow hoang đảo / Bản chất con người / Trí tuệ nguyên thủy', 'golden_hook': "Tổng tài ném chiếc thẻ đen không giới hạn hạn mức vào đống tro tàn trước mặt tôi: 'Tôi cho ông mười tỷ, bán cho tôi nửa chai nước ngọt và con cá nướng đó!'. Tôi thong thả cắn ngập miệng thịt cá, cười nhạt: 'Ở đây, tờ tiền của anh không đáng giá bằng một hòn than củi sưởi ấm!'.", 'author_platform': 'Tri Hồ - Zhihu (Sinh tồn thực tế)', 'core_lessons': ['Giải thiêng Giá trị đồng tiền (Devaluing Currency in Crisis): Đặt nhân vật vào hoàn cảnh cực đoan để bộc lộ rõ nhất giá trị của lao động chân chính và kỹ năng sinh tồn thực tế.', 'Khắc họa tâm lý xã hội học sâu sắc: Sự chuyển biến tâm lý từ ích kỷ sang đoàn kết tương trợ lẫn nhau mang lại giá trị nhân văn cao đẹp.', "Mẹo chuyển thể Audio TikTok: Tiếng cọ xát của hai thanh gỗ đánh lửa 'xoẹt xoẹt xoẹt', tiếng ngọn lửa bùng lên tanh tách mang lại sự nhẹ nhõm vô bờ."]}, {'id': '100', 'title_vi': 'Thời Không Tuần Hoàn: Khai Đoan', 'title_cn': '时空循环：开端', 'author': 'Kỳ Đảo Quân (祈祷君)', 'platform': 'Jinjiang & Phim truyền hình hiện tượng quốc gia', 'category': 'Vòng lặp thời gian / Điều tra phá án / Trách nhiệm công dân / Đại kết cục viên mãn', 'premise': 'Nữ sinh viên Lý Thi Tình và chàng lập trình viên Tiêu Hạc Vân bị mắc kẹt trong một vòng lặp thời gian bí ẩn trên chuyến xe buýt số 45 chuẩn bị phát nổ khi đi qua cầu Thập Tự. Cứ sau mỗi vụ nổ thảm khốc, họ lại thức tỉnh trên ghế xe buýt trước thời điểm nổ vài phút. Trải qua hơn 20 lần chết đi sống lại trong đau đớn và hoảng loạn, hai người trẻ tuổi bình thường quyết định không chạy trốn một mình mà cùng nhau tìm ra quả bom giấu trong nồi áp suất, giải mã động cơ đau lòng của đôi vợ chồng tài xế và cứu sống toàn bộ hành khách trên xe.', 'characters': ["Lý Thi Tình: Nhạy cảm, giàu lòng trắc ẩn, người đầu tiên rơi vào vòng lặp thời gian và kiên quyết cứu lấy mọi người. Mỏ neo: Bản nhạc chuông điện thoại bài hát 'Canon' định mệnh.", 'Tiêu Hạc Vân: Thực tế, lý trí, ban đầu muốn trốn chạy một mình nhưng dần bị lòng dũng cảm của Thi Tình cảm hóa, sẵn sàng đem thân mình đè lên quả bom.', 'Bác tài xế & Người phụ nữ ôm nồi áp suất: Đôi vợ chồng tuyệt vọng ôm mối hận thù về cái chết oan ức của con gái năm xưa.'], 'hook_3s': "Bản nhạc chuông điện thoại bài Canon vừa vang lên réo rắt trong khoang xe, người phụ nữ ôm chiếc nồi áp suất bọc trong bao tải màu đỏ dưới chân bỗng đứng dậy, tay cầm sẵn chiếc kíp nổ giật chốt: 'Mọi người... cùng xuống địa ngục với con gái tôi đi!'.", 'act_structure': {'act_1': 'Hồi 1 (Những vòng lặp đầu tiên đầy sợ hãi): Bị nổ tung nhiều lần; thử các cách xuống xe giả vờ bệnh tật, quấy rối nhưng xe vẫn nổ cướp đi sinh mạng những người khác.', 'act_2': 'Hồi 2 (Điều tra tìm ra quả bom và hung thủ): Từng bước thu hẹp diện nghi vấn; phát hiện quả bom tự chế nằm trong nồi áp suất của người phụ nữ mặc áo xám; giải mã cái chết của cô con gái Vương Manh Manh 5 năm trước.', 'act_3': 'Hồi 3 (Vòng lặp cuối cùng - Toàn thắng tuyệt đối): Bắt tay cùng các hành khách trên xe (anh chàng giao hàng, chú vác bao tải tải, bác sĩ) khống chế hung thủ, tháo ngòi nổ quả bom trên cầu, giải oan cho người con gái và phá vỡ vòng lặp vĩnh viễn.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Vòng lặp thời gian không phải là sự trừng phạt; đó là cơ hội cứu chuộc lương tri mà ý thức của cô con gái đã khuất tạo ra để ngăn cản cha mẹ mình bước vào con đường tội ác diệt vong.', 'mastery_takeaways': ['Khái niệm Vòng lặp thời gian không gian hẹp (Time Loop in Confined Space): Giới hạn không gian trên một chuyến xe buýt và thời gian đếm ngược 10 phút tạo độ căng thẳng tột cùng (Extreme Tension).', 'Sức mạnh của Lòng trắc ẩn và Sự dũng cảm của người bình thường: Hai người trẻ không có siêu năng lực, chỉ có trái tim nhân ái đã làm nên điều kỳ diệu cứu vớt số phận.', 'Khép lại hoàn hảo 100 tác phẩm kinh điển: Một câu chuyện vĩ đại về tình người, công lý và sự cứu rỗi khép lại toàn bộ Đại Điển Tri Thức Kịch Bản Bách Khoa Toàn Thư.', "Mẹo chuyển thể Audio TikTok: Bản nhạc chuông 'Canon' phát ra từ đầu video tạo phản xạ có điều kiện nổi da gà cho người nghe, tiếng nổ 'Bùm' rung chuyển điện thoại."], 'title_vn': 'Thời Không Tuần Hoàn: Khai Đoan', 'genre': 'Vòng lặp thời gian / Điều tra phá án / Trách nhiệm công dân / Đại kết cục viên mãn', 'golden_hook': "Bản nhạc chuông điện thoại bài Canon vừa vang lên réo rắt trong khoang xe, người phụ nữ ôm chiếc nồi áp suất bọc trong bao tải màu đỏ dưới chân bỗng đứng dậy, tay cầm sẵn chiếc kíp nổ giật chốt: 'Mọi người... cùng xuống địa ngục với con gái tôi đi!'.", 'author_platform': 'Kỳ Đảo Quân (祈祷君) - Jinjiang & Phim truyền hình hiện tượng quốc gia', 'core_lessons': ['Khái niệm Vòng lặp thời gian không gian hẹp (Time Loop in Confined Space): Giới hạn không gian trên một chuyến xe buýt và thời gian đếm ngược 10 phút tạo độ căng thẳng tột cùng (Extreme Tension).', 'Sức mạnh của Lòng trắc ẩn và Sự dũng cảm của người bình thường: Hai người trẻ không có siêu năng lực, chỉ có trái tim nhân ái đã làm nên điều kỳ diệu cứu vớt số phận.', 'Khép lại hoàn hảo 100 tác phẩm kinh điển: Một câu chuyện vĩ đại về tình người, công lý và sự cứu rỗi khép lại toàn bộ Đại Điển Tri Thức Kịch Bản Bách Khoa Toàn Thư.', "Mẹo chuyển thể Audio TikTok: Bản nhạc chuông 'Canon' phát ra từ đầu video tạo phản xạ có điều kiện nổi da gà cho người nghe, tiếng nổ 'Bùm' rung chuyển điện thoại."]}]
